<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Users</h1><p><?= (int) $total ?> account<?= $total === 1 ? '' : 's' ?> match the filters.</p></div></div>
<form class="filter-bar admin-filter" method="get" action="<?= h(app_url('admin.users')) ?>"><input type="hidden" name="r" value="admin.users"><div class="form-field search-span"><label for="q">Search</label><input id="q" name="q" value="<?= h($q) ?>" placeholder="Name or email"></div><div class="form-field"><label for="role">Role</label><select id="role" name="role"><option value="">All roles</option><?php foreach (['STUDENT'=>'Student','VENDOR'=>'Vendor','ADMIN'=>'Administrator'] as $key=>$label): ?><option value="<?= h($key) ?>"<?= $role===$key?' selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option><option value="ACTIVE"<?= $status==='ACTIVE'?' selected':'' ?>>Active</option><option value="SUSPENDED"<?= $status==='SUSPENDED'?' selected':'' ?>>Suspended</option></select></div><button class="button" type="submit">Filter</button></form>
<?php if ($users): ?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Created</th><th>Status</th><th>Access</th></tr></thead><tbody><?php foreach ($users as $record): ?><tr><td><div class="row"><span class="workspace-avatar workspace-avatar-small" aria-hidden="true"><?php if (!empty($record['profile_media_id'])): ?><img src="<?= h(app_url('media.view', ['id' => (int) $record['profile_media_id']])) ?>" alt="" loading="lazy"><?php else: ?><?= h(mb_strtoupper(mb_substr($record['full_name'], 0, 1, 'UTF-8'), 'UTF-8')) ?><?php endif; ?></span><div><strong><?= h($record['full_name']) ?></strong><?php if ($record['phone']): ?><div class="muted small"><?= h($record['phone']) ?></div><?php endif; ?></div></div></td><td><?= h($record['email']) ?></td><td><?= h(ucfirst(strtolower($record['role']))) ?></td><td><?= h(format_datetime($record['created_at'], 'M j, Y')) ?></td><td><?php $status=$record['status']; require APP_ROOT . '/views/components/status-badge.php'; ?></td><td><form method="post" action="<?= h(app_url('admin.user.status')) ?>" data-confirm="<?= $record['status']==='ACTIVE'?'Suspend':'Activate' ?> <?= h($record['full_name']) ?>?" class="inline-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $record['id'] ?>"><button class="button button-secondary button-small" type="submit"><?= $record['status']==='ACTIVE'?'Suspend':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php $routeName='admin.users';$perPage=$limit;$queryParams=array_filter(['q'=>$q,'role'=>$role,'status'=>$status]);require APP_ROOT . '/views/components/pagination.php'; ?><?php else: ?><div class="empty-state"><h2>No matching users</h2><p>Try clearing one of the filters.</p></div><?php endif; ?>
